use xiom.io;

use xiom.string;
fn set_difference(a: &Set[Int], b: &Set[Int], a_list: &Vec[Int]) -> Vec[Int] {
  let result: Vec[Int] = Vec[Int].new();
  let i = 0;
  while i < a_list.len() {
    let item = match a_list.get(i) { Some(v) => v, None => 0 };
    if !b.contains(&item) {
      result.push(item);
    }
    i = i + 1;
  }
  return result;
}

fn set_intersection(a: &Set[Int], b: &Set[Int], a_list: &Vec[Int]) -> Vec[Int] {
  let result: Vec[Int] = Vec[Int].new();
  let i = 0;
  while i < a_list.len() {
    let item = match a_list.get(i) { Some(v) => v, None => 0 };
    if b.contains(&item) {
      result.push(item);
    }
    i = i + 1;
  }
  return result;
}

fn main() -> Int {
  let set_a: Set[Int] = Set[Int].new();
  set_a.insert(1); set_a.insert(2); set_a.insert(3); set_a.insert(4);
  let list_a: Vec[Int] = Vec[Int].new();
  list_a.push(1); list_a.push(2); list_a.push(3); list_a.push(4);

  let set_b: Set[Int] = Set[Int].new();
  set_b.insert(3); set_b.insert(4); set_b.insert(5);

  let diff = set_difference(&set_a, &set_b, &list_a);
  let inter = set_intersection(&set_a, &set_b, &list_a);
  io.println("Diff: " + to_string(diff.len()));
  io.println("Inter: " + to_string(inter.len()));
  return 0;
}
